import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const directory = path.dirname(fileURLToPath(import.meta.url));
const databasePath = process.env.DB_PATH || path.join(directory, 'workboard.sqlite');
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
  )
`);
database.exec('PRAGMA foreign_keys = ON');
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}

const indexHtml = await readFile(path.join(directory, 'public', 'index.html'));
const clientJs = await readFile(path.join(directory, 'public', 'app.js'));
const stylesCss = await readFile(path.join(directory, 'public', 'styles.css'));

function sendJson(response, status, body) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

const server = http.createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const projects = database.prepare(`
      SELECT projects.id, projects.name, projects.archived,
        COUNT(tasks.id) AS totalCount,
        COALESCE(SUM(tasks.completed), 0) AS completedCount
      FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
      GROUP BY projects.id ORDER BY projects.id
    `).all();
    return sendJson(response, 200, projects.map(project => ({
      ...project, archived: Boolean(project.archived), totalCount: Number(project.totalCount), completedCount: Number(project.completedCount)
    })));
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    const input = await readJson(request);
    const name = typeof input?.name === 'string' ? input.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'GET' && projectMatch) {
    const project = database.prepare(`SELECT id, name, archived FROM projects WHERE id = ?`).get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, { ...project, archived: Boolean(project.archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }
  if (request.method === 'PATCH' && projectMatch) {
    const input = await readJson(request);
    const name = typeof input?.name === 'string' ? input.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const projectId = Number(projectMatch[1]);
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot be renamed' });
    database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
    return sendJson(response, 200, { id: projectId, name, archived: false });
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (request.method === 'POST' && archiveMatch) {
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, { status: 'ok' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id').all(projectId);
    return sendJson(response, 200, tasks.map(task => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksMatch && request.method === 'POST') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId).archived) return sendJson(response, 409, { error: 'Archived projects cannot have tasks' });
    const input = await readJson(request);
    const title = typeof input?.title === 'string' ? input.title.trim() : '';
    if (!title) return sendJson(response, 400, { error: 'Task title is required' });
    const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    const input = await readJson(request);
    const existing = database.prepare('SELECT tasks.id, projects.archived FROM tasks JOIN projects ON projects.id = tasks.project_id WHERE tasks.id = ?').get(Number(taskMatch[1]));
    if (!existing) return sendJson(response, 404, { error: 'Task not found' });
    if (existing?.archived) return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
    if (typeof input?.completed === 'boolean') {
      database.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(Number(input.completed), Number(taskMatch[1]));
    } else if (typeof input?.title === 'string') {
      const title = input.title.trim();
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      database.prepare('UPDATE tasks SET title = ? WHERE id = ?').run(title, Number(taskMatch[1]));
    } else if (typeof input?.priority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(input.priority)) return sendJson(response, 400, { error: 'Invalid task priority' });
      database.prepare('UPDATE tasks SET priority = ? WHERE id = ?').run(input.priority, Number(taskMatch[1]));
    } else {
      return sendJson(response, 400, { error: 'A task title, completion value, or priority is required' });
    }
    const task = database.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE id = ?').get(Number(taskMatch[1]));
    return sendJson(response, 200, { ...task, completed: Boolean(task.completed) });
  }
  if (request.method === 'GET' && url.pathname === '/') {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return response.end(indexHtml);
  }
  if (request.method === 'GET' && url.pathname === '/app.js') {
    response.writeHead(200, { 'content-type': 'text/javascript; charset=utf-8' });
    return response.end(clientJs);
  }
  if (request.method === 'GET' && url.pathname === '/styles.css') {
    response.writeHead(200, { 'content-type': 'text/css; charset=utf-8' });
    return response.end(stylesCss);
  }
  const pageMatch = url.pathname.match(/^\/projects\/(\d+)$/);
  if (request.method === 'GET' && pageMatch) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return response.end(indexHtml);
  }
  response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

function showError(message) {
  const alert = element('p', message, { role: 'alert' });
  app.prepend(alert);
}

async function renderList() {
  app.replaceChildren(element('h1', 'Workboard'));
  const filterLabel = element('label', 'Project filter', { for: 'project-filter' });
  const filter = element('select', undefined, { id: 'project-filter', name: 'filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value: value.toLowerCase() }));
  filterLabel.append(filter);
  app.append(filterLabel);
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text' });
  const submit = element('button', 'Create project', { type: 'submit' });
  form.append(label, input, submit);
  app.append(form);
  const list = element('section', undefined, { 'aria-label': 'Projects' });
  app.append(list);
  try {
    const projects = await getProjects();
    const renderProjects = () => {
      list.replaceChildren();
      for (const project of projects.filter(item => item.archived === (filter.value === 'archived'))) {
      const row = element('article', undefined, { 'data-testid': 'project-row', class: 'project-row' });
      row.append(element('span', project.name));
      row.append(element('span', `${project.completedCount}/${project.totalCount} completed`, { 'data-testid': 'project-summary' }));
      const open = element('button', 'Open project', { type: 'button' });
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      row.append(open);
      const action = project.archived ? 'Restore project' : 'Archive project';
      const archive = element('button', action, { type: 'button' });
      archive.addEventListener('click', async () => {
        const response = await fetch(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
        if (!response.ok) return showError(`Could not ${project.archived ? 'restore' : 'archive'} project`);
        renderList();
      });
      row.append(archive);
      list.append(row);
      }
    };
    renderProjects();
    filter.addEventListener('change', renderProjects);
  } catch {
    showError('Could not load projects');
  }
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      showError('Project name is required');
      return;
    }
    try {
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (!response.ok) throw new Error('Could not create project');
      renderList();
    } catch {
      showError('Could not create project');
    }
  });
}

async function renderProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => { location.href = '/'; });
  app.append(back);
  try {
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
    if (!response.ok) throw new Error('Project not found');
    const project = await response.json();
    const heading = element('h1', project.name);
    app.append(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', 'New project name', { for: 'new-project-name' });
    const renameInput = element('input', undefined, { id: 'new-project-name', name: 'name', type: 'text' });
    const renameButton = element('button', 'Rename project', { type: 'submit' });
    renameInput.disabled = project.archived;
    renameButton.disabled = project.archived;
    renameForm.append(renameLabel, renameInput, renameButton);
    app.append(renameForm);
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) {
        showError('Project name is required');
        return;
      }
      try {
        const renamed = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (!renamed.ok) throw new Error('Could not rename project');
        const saved = await renamed.json();
        heading.textContent = saved.name;
        renameInput.value = '';
      } catch {
        showError('Could not rename project');
      }
    });
    const form = element('form');
    const label = element('label', 'Task title', { for: 'task-title' });
    const input = element('input', undefined, { id: 'task-title', name: 'title', type: 'text' });
    const createButton = element('button', 'Create task', { type: 'submit' });
    createButton.disabled = project.archived;
    form.append(label, input, createButton);
    app.append(form);

    const filterLabel = element('label', 'Task filter', { for: 'task-filter' });
    const filter = element('select', undefined, { id: 'task-filter', name: 'filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value: value.toLowerCase() }));
    filterLabel.append(filter);
    app.append(filterLabel);
    const priorityFilterLabel = element('label', 'Priority filter', { for: 'priority-filter' });
    const priorityFilter = element('select', undefined, { id: 'priority-filter', name: 'priority-filter' });
    for (const value of ['All', 'Low', 'Normal', 'High']) priorityFilter.append(element('option', value, { value: value.toLowerCase() }));
    priorityFilterLabel.append(priorityFilter);
    app.append(priorityFilterLabel);
    const list = element('section', undefined, { 'aria-label': 'Tasks' });
    app.append(list);

    let tasks = [];
    const renderTasks = () => {
      list.replaceChildren();
      const visible = tasks.filter(task =>
        (filter.value === 'all' || (filter.value === 'completed' ? task.completed : !task.completed)) &&
        (priorityFilter.value === 'all' || (task.priority || 'Normal').toLowerCase() === priorityFilter.value)
      );
      for (const task of visible) {
        const row = element('article', undefined, { 'data-testid': 'task-row', class: 'task-row' });
        row.append(element('span', task.title));
        const checkbox = element('input', undefined, { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = task.completed;
        checkbox.disabled = project.archived;
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          try {
            const update = await fetch(`/api/tasks/${task.id}`, {
              method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked })
            });
            if (!update.ok) throw new Error('Could not update task');
            const saved = await update.json();
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            renderTasks();
          } catch {
            checkbox.checked = task.completed;
            checkbox.disabled = false;
            showError('Could not update task');
          }
        });
        row.append(checkbox);
        const priorityLabel = element('label', 'Task priority', { for: `task-priority-${task.id}` });
        const priority = element('select', undefined, { id: `task-priority-${task.id}`, name: 'priority' });
        for (const value of ['Low', 'Normal', 'High']) priority.append(element('option', value, { value }));
        let savedPriority = task.priority || 'Normal';
        priority.value = savedPriority;
        priority.disabled = project.archived;
        priority.addEventListener('change', async () => {
          priority.disabled = true;
          try {
            const update = await fetch(`/api/tasks/${task.id}`, {
              method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: priority.value })
            });
            if (!update.ok) throw new Error('Could not update task priority');
            const saved = await update.json();
            savedPriority = saved.priority;
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            renderTasks();
          } catch {
            priority.value = savedPriority;
            showError('Could not update task priority');
          } finally {
            priority.disabled = project.archived;
          }
        });
        row.append(priorityLabel, priority);
        const renameForm = element('form');
        const renameLabel = element('label', 'New task title', { for: `new-task-title-${task.id}` });
        const renameInput = element('input', undefined, { id: `new-task-title-${task.id}`, name: 'title', type: 'text', value: task.title });
        const renameButton = element('button', 'Rename task', { type: 'submit' });
        renameInput.disabled = project.archived;
        renameButton.disabled = project.archived;
        renameForm.append(renameLabel, renameInput, renameButton);
        renameForm.addEventListener('submit', async event => {
          event.preventDefault();
          const title = renameInput.value.trim();
          if (!title) {
            showError('Task title is required');
            return;
          }
          try {
            const update = await fetch(`/api/tasks/${task.id}`, {
              method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
            });
            if (!update.ok) throw new Error('Could not rename task');
            const saved = await update.json();
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            renderTasks();
          } catch {
            showError('Could not rename task');
          }
        });
        row.append(renameForm);
        list.append(row);
      }
    };
    filter.addEventListener('change', renderTasks);
    priorityFilter.addEventListener('change', renderTasks);
    const tasksResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
    if (!tasksResponse.ok) throw new Error('Could not load tasks');
    tasks = await tasksResponse.json();
    renderTasks();

    form.addEventListener('submit', async event => {
      event.preventDefault();
      const title = input.value.trim();
      if (!title) {
        showError('Task title is required');
        return;
      }
      try {
        const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
        });
        if (!created.ok) throw new Error('Could not create task');
        tasks.push(await created.json());
        input.value = '';
        renderTasks();
      } catch {
        showError('Could not create task');
      }
    });
  } catch {
    app.append(element('h1', 'Project not found'));
  }
}

